CREATE TABLE users ( id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, phone TEXT, password_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended','banned')), is_staff INTEGER NOT NULL DEFAULT 0 CHECK (is_staff IN (0,1)), email_verified_at TEXT, last_login_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX idx_users_staff ON users(is_staff);
CREATE INDEX idx_users_created ON users(created_at);
CREATE TABLE sessions ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf_token TEXT NOT NULL, ip TEXT, user_agent TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), rotated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), expires_at TEXT NOT NULL );
CREATE INDEX idx_sessions_user ON sessions(user_id);
CREATE INDEX idx_sessions_exp ON sessions(expires_at);
CREATE TABLE password_reset_tokens ( token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL, used_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX idx_prt_user ON password_reset_tokens(user_id);
CREATE TABLE email_verification_tokens ( token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL, used_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX idx_evt_user ON email_verification_tokens(user_id);
CREATE TABLE rate_limits ( key TEXT PRIMARY KEY, count INTEGER NOT NULL, window_start INTEGER NOT NULL );
CREATE TABLE roles ( id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT );
CREATE TABLE permissions ( code TEXT PRIMARY KEY, description TEXT NOT NULL );
CREATE TABLE role_permissions ( role_id TEXT NOT NULL REFERENCES roles(id) ON DELETE CASCADE, permission_code TEXT NOT NULL REFERENCES permissions(code) ON DELETE CASCADE, PRIMARY KEY (role_id, permission_code) );
CREATE TABLE user_roles ( user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, role_id TEXT NOT NULL REFERENCES roles(id) ON DELETE CASCADE, PRIMARY KEY (user_id, role_id) );
CREATE TABLE product_categories ( id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT, icon TEXT, sort_order INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)) );
CREATE TABLE provider_integrations ( id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, base_url TEXT, enabled INTEGER NOT NULL DEFAULT 0 CHECK (enabled IN (0,1)), config TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'awaiting_credentials', last_checked_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE TABLE products ( id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, category_id TEXT NOT NULL REFERENCES product_categories(id), name TEXT NOT NULL, short_description TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', image_key TEXT, brand_color TEXT NOT NULL DEFAULT '#087BFF', status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','active','hidden')), delivery_type TEXT NOT NULL DEFAULT 'manual' CHECK (delivery_type IN ('automatic','manual','api')), features TEXT NOT NULL DEFAULT '[]', input_fields TEXT NOT NULL DEFAULT '[]', terms TEXT NOT NULL DEFAULT '', refund_eligible INTEGER NOT NULL DEFAULT 0 CHECK (refund_eligible IN (0,1)), refund_policy TEXT NOT NULL DEFAULT '', is_featured INTEGER NOT NULL DEFAULT 0 CHECK (is_featured IN (0,1)), is_trending INTEGER NOT NULL DEFAULT 0 CHECK (is_trending IN (0,1)), is_deal INTEGER NOT NULL DEFAULT 0 CHECK (is_deal IN (0,1)), is_demo INTEGER NOT NULL DEFAULT 0 CHECK (is_demo IN (0,1)), sales_count INTEGER NOT NULL DEFAULT 0, provider_id TEXT REFERENCES provider_integrations(id), seo_title TEXT, seo_description TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX idx_products_cat ON products(category_id, status);
CREATE INDEX idx_products_status ON products(status);
CREATE INDEX idx_products_flags ON products(is_featured, is_trending, is_deal);
CREATE TABLE product_plans ( id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE, name TEXT NOT NULL, duration_label TEXT NOT NULL DEFAULT '', price INTEGER NOT NULL CHECK (price > 0), compare_price INTEGER CHECK (compare_price IS NULL OR compare_price >= 0), stock_limit INTEGER CHECK (stock_limit IS NULL OR stock_limit >= 0), provider_sku TEXT, status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','hidden')), sort_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX idx_plans_product ON product_plans(product_id, status);
CREATE TABLE product_inventory ( id TEXT PRIMARY KEY, plan_id TEXT NOT NULL REFERENCES product_plans(id) ON DELETE CASCADE, secret_enc TEXT NOT NULL, secret_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'available' CHECK (status IN ('available','delivered','void')), order_item_id TEXT, created_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), delivered_at TEXT, UNIQUE (plan_id, secret_hash) );
CREATE INDEX idx_inv_avail ON product_inventory(plan_id, status);
